import React from "react";
import "./ChipBar.css";

interface ChipBarProps {
  statuses: string[];
  selected: Set<string>;
  onSelectionChange: (next: Set<string>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps) {
  function toggle(status: string) {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter by status">
      {statuses.map((status) => {
        const pressed = selected.has(status);
        return (
          <button
            key={status}
            className={`chip${pressed ? " chip--pressed" : ""}`}
            aria-pressed={pressed}
            onClick={() => toggle(status)}
          >
            {status}
          </button>
        );
      })}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { fetchBooks } from './api';
import { ShelfGrid } from './components/ShelfGrid/ShelfGrid';
import type { Book } from './types';

const SKELETON_COUNT = 6;

export default function App() {
  // null = loading; array (possibly empty) = loaded
  const [books, setBooks] = useState<Book[] | null>(null);

  useEffect(() => {
    fetchBooks().then(setBooks);
  }, []);

  return <ShelfGrid books={books} skeletonCount={SKELETON_COUNT} />;
}

