import React, { useState } from "react";
import "./ChipBar.css";

// Owns only visual pressed state; grid filtering is not wired.

interface ChipBarProps {
  chips: string[];
}

export function ChipBar({ chips }: ChipBarProps) {
  const [pressed, setPressed] = useState<string | null>(null);

  return (
    <div className="chip-bar">
      {chips.map((chip) => (
        <button
          key={chip}
          className={`chip${pressed === chip ? " chip--pressed" : ""}`}
          onClick={() => setPressed(pressed === chip ? null : chip)}
          aria-pressed={pressed === chip}
        >
          {chip}
        </button>
      ))}
    </div>
  );
}

